fn estimate_oethb_required(weth_amount: u128, sqrt_price_x96: u128, sqrt_lower_x96: u128, sqrt_upper_x96: u128) -> u128 {
    // Uniswap v3 concentrated liquidity: L = amount0 * sqrtP * sqrtLower / (Q96 * (sqrtUpper - sqrtLower))
    // amount1 = L * (sqrtP - sqrtLower) / Q96
    // Simplified integer approximation (matches estimateAmount1 semantics):
    let q96: u128 = 79_228_162_514_264_337_593_543_950_336u128;
    // L numerator: weth * sqrtP * sqrtLower
    // Use u256 approximation via scaling to avoid overflow in pure u128
    let sqrt_diff = sqrt_price_x96.saturating_sub(sqrt_lower_x96);
    let sqrt_range = sqrt_upper_x96.saturating_sub(sqrt_lower_x96);
    // amount1 = weth_amount * sqrtP * (sqrtP - sqrtLower) / (sqrtLower * (sqrtUpper - sqrtLower)) scaled by Q96^0
    // Simplified: oethb = weth * (sqrtP - sqrtLower) * sqrtP / (sqrt_range * sqrtLower) -- matches Uniswap v3 math direction
    let numerator = weth_amount
        .saturating_mul(sqrt_diff / (q96 / 1_000_000))
        .saturating_mul(sqrt_price_x96 / (q96 / 1_000_000));
    let denominator = (sqrt_range / (q96 / 1_000_000))
        .saturating_mul(sqrt_lower_x96 / (q96 / 1_000_000));
    if denominator == 0 { return 0; }
    numerator / denominator
}
